Given an array arr[] consisting of n integers,  find all the array elements which occurs more than floor(n/3) times.Note: The returned array of majority elements should be sorted.Examples:Input: arr[] = [2, 2, 3, 1, 3, 2, 1, 1]Output: [1, 2]Explanation: The frequency of 1 and 2 is 3, which is more than floor n/3 (8/3 = 2).Input: arr[] = [-5, 3, -5]Output: [-5]Explanation: The frequency of -5 is 2, which is more than floor n/3 (3/3 = 1).Input: arr[] = [3, 2, 2, 4, 1, 4]Output: [ ]Explanation: There is no majority element.Try It YourselfTable of Content[Naive Approach] Using Nested Loops - O(n^2) Time and O(1) Space[Expected Approach] Boyer-Moore’s Voting Algorithm - O(n) Time and O(1) Space[Naive Approach] Using Nested Loops - O(n^2) Time and O(1) SpaceThe idea is to iterate over all elements and count the frequency of the element in the array. If the frequency of the element is greater than floor(n/3), add it to the result. To avoid adding duplicate elements into the result, we can check if the element is already present in the result. We can stop the iteration if we have already found two majority elements.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> findMajority(vector<int> &arr) {
    int n = arr.size();
    vector<int> res;

    for (int i = 0; i < n; i++) {

        // Count the frequency of arr[i]
        int cnt = 0;
        for (int j = i; j < n; j++) {
            if (arr[j] == arr[i])
                cnt += 1;
        }

        // Check if arr[i] is a majority element
        if (cnt > (n / 3)) {

            // Add arr[i] only if it is not already
            // present in the result
            if (res.size() == 0 || arr[i] != res[0]) {
                res.push_back(arr[i]);
            }
        }

        // If we have found two majority elements, 
        // we can stop our search
        if (res.size() == 2) {
            if(res[0] > res[1])
                swap(res[0], res[1]);
            break;
        }
    }

    return res;
}

int main() {
    vector<int> arr = {2, 2, 3, 1, 3, 2, 1, 1};
    vector<int> res = findMajority(arr);
    for (int ele : res)
        cout << ele << " ";
    return 0;
}


